// spec: specs/orders.md §7 · кейс .qa/tests/orders/ord-20-new-order-toast-list-sync.md
// seed: tests/seed.admin.spec.ts (+ buyer через asUser)
// #d9d645 (עבר QA 21.10): у admin на /orders в момент появления тоста «התקבלה הזמנה חדשה · #N · test» заказ #N уже первая
// строка списка (без перезагрузки). Опрос новых заказов ~20 с (+ до 4 с ожидания списка) → тест долгий.
// Две роли: admin (окно /orders с MutationObserver) и buyer (отправляет заказ). Данные: свой товар QA-AUTO-d9d6-<ts> (₪1, остаток 3)
// и заказ «QA-AUTO-d9d6-<ts>»; afterAll — заказ отклоняется, товар удаляется. Корзина buyer общая → @orders, не параллельно.
import { test, expect } from '../../fixtures';
import { createStockedProduct, placeOrder, cleanup } from './_qa-order';

test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-d9d6-${TS}`;
let orderNo: string | undefined;
let productCreated = false;

type Seen = { toast: string; firstRow: string; dt: number };

test.describe('orders — הזמנה חדשה כבר בשורה הראשונה כשמופיעה ההתראה (#d9d645)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [orderNo], productCreated ? [P] : []);
  });

  test('ברגע שמופיע «התקבלה הזמנה חדשה · #N» — #N כבר ראשונה ברשימה, בלי רענון #d9d645 @desktop @orders @data', async ({ asUser }) => {
    test.setTimeout(240_000);
    const admin = await asUser('admin');
    const buyer = await asUser('buyer');

    productCreated = true;
    const productId = await createStockedProduct(admin, P, `QAD9D6${TS}`, 1, 3);

    await admin.goto('/orders');
    await expect(admin.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
    await expect(admin.getByRole('button', { name: /^#\d+ / }).first()).toBeVisible({ timeout: 30_000 });
    // наблюдатель: в момент первого появления тоста запоминаем текст первой строки списка
    await admin.evaluate(() => {
      const w = window as unknown as { __seen?: Seen[] };
      type Seen = { toast: string; firstRow: string; dt: number };
      w.__seen = [];
      const t0 = performance.now();
      const firstRow = () =>
        ([...document.querySelectorAll('main [role="button"][tabindex]')] as HTMLElement[])
          .map((e) => (e.textContent || '').trim())
          .find((t) => /^#\d+/.test(t)) || '';
      const check = () => {
        const toasts = ([...document.querySelectorAll('body *')] as HTMLElement[])
          .filter((e) => e.children.length === 0 && /התקבלה הזמנה חדשה/.test(e.textContent || ''))
          .map((e) => (e.parentElement?.textContent || '').replace(/\s+/g, ' ').trim());
        for (const t of toasts) if (!w.__seen!.some((s) => s.toast === t)) w.__seen!.push({ toast: t, firstRow: firstRow(), dt: performance.now() - t0 });
      };
      new MutationObserver(check).observe(document.body, { childList: true, subtree: true, characterData: true });
    });

    orderNo = await placeOrder(buyer, [{ id: productId, name: P, qty: 1 }], `QA-AUTO-d9d6-${TS}`);

    // ждём тост именно об этом заказе (цикл опроса ~20 с)
    await expect(admin.getByText(new RegExp(`#${orderNo}\\b`)).filter({ hasNotText: /^#\d+ test/ }).first()).toBeVisible({ timeout: 60_000 });
    const seen = await admin.evaluate(() => (window as unknown as { __seen: Seen[] }).__seen);
    const mine = seen.find((s) => s.toast.includes(`#${orderNo}`));
    expect(mine, `тост о #${orderNo} пойман наблюдателем: ${JSON.stringify(seen)}`).toBeTruthy();
    expect(mine!.toast).toMatch(/התקבלה הזמנה חדשה/);
    expect(mine!.toast).toContain('test');
    expect(mine!.firstRow, `в момент тоста первая строка — #${orderNo}`).toMatch(new RegExp(`^#${orderNo}\\D`));
    // и в списке без перезагрузки: первая строка — новый заказ «ממתינה לאישור»
    await expect(admin.getByRole('button', { name: /^#\d+ / }).first()).toHaveAccessibleName(new RegExp(`^#${orderNo} test .*ממתינה לאישור`));
  });
});
